.cs-tag-suggest {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-top: 8px;
}
.cs-tag-chip {
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(14, 165, 233, 0.14);
  border: 1px solid rgba(14, 165, 233, 0.4);
  color: #0ea5e9;
  font-weight: 700;
  cursor: pointer;
  font-size: 0.85rem;
}
.cs-tag-chip:hover {
  background: rgba(14, 165, 233, 0.25);
}

js:
(function() {
  'use strict';
  if (window.__CS_TAG_SUGGESTER__) return;
  window.__CS_TAG_SUGGESTER__ = true;

  const api = window.CardSpoke?.utils;
  const tagMap = {
    design: ['ui', 'ux', 'layout', 'figma', 'flow'],
    research: ['note', 'insight', 'interview', 'data', 'experiment'],
    marketing: ['campaign', 'launch', 'copy', 'press'],
    engineering: ['bug', 'api', 'deploy', 'release', 'build'],
    priority: ['urgent', 'p0', 'p1']
  };

  const findMatches = (text) => {
    const lower = (text || '').toLowerCase();
    const found = new Set();
    Object.entries(tagMap).forEach(([tag, keywords]) => {
      if (keywords.some((k) => lower.includes(k))) found.add(tag);
    });
    return Array.from(found);
  };

  const applyTag = async (cardId, tag) => {
    try {
      await api?.addTag?.(cardId, tag);
      api?.showToast?.(`Tag added: ${tag}`);
    } catch (e) {
      console.error(e);
      api?.showToast?.('Unable to add tag', 'error');
    }
  };

  const render = () => {
    document.querySelectorAll('.card-detail, .card').forEach((card, idx) => {
      const header = card.querySelector('.card-detail-header, .card-header');
      const body = card.querySelector('.card-detail-body, .card-body');
      if (!header || !body) return;
      const cardId = card.dataset.cardId || card.getAttribute('data-id') || `card-${idx}`;
      let bar = header.querySelector('.cs-tag-suggest');
      if (!bar) {
        bar = document.createElement('div');
        bar.className = 'cs-tag-suggest';
        header.appendChild(bar);
      }
      bar.innerHTML = '';
      const matches = findMatches(body.textContent || '');
      matches.forEach((tag) => {
        const chip = document.createElement('span');
        chip.className = 'cs-tag-chip';
        chip.textContent = `+ ${tag}`;
        chip.title = 'Click to apply tag';
        chip.addEventListener('click', () => applyTag(cardId, tag));
        bar.appendChild(chip);
      });
    });
  };

  const observer = new MutationObserver(() => setTimeout(render, 60));

  const enable = () => {
    render();
    observer.observe(document.body, { childList: true, subtree: true });
    api?.showToast?.('Context Tag Suggester active');
  };

  const disable = () => {
    observer.disconnect();
    document.querySelectorAll('.cs-tag-suggest').forEach((el) => el.remove());
  };

  if (window.CardSpoke_MODS?.register) {
    CardSpoke_MODS.register('plugin-context-tag-suggester', {
      meta: { name: 'Context Tag Suggester', type: 'Plugin', version: '1.0.0' },
      onAppInit: enable,
      onCardRender: render,
      onDisable: disable,
      onUninstall: disable
    });
  } else {
    enable();
  }
})();
